import {byNode} from './constellation.js';
import {questionLevel,questionSeconds} from './journey.js';
import {OBJECTS,WORLD_OBJECTS} from './math-objects.js';
export function novaProblem(state,node,index=0,now=Date.now(),seed=Math.floor(Math.random()*4294967296)){
 let cursor=seed>>>0;const rand=(a,b)=>{cursor=(Math.imul(1664525,cursor)+1013904223)>>>0;return a+Math.floor(cursor/4294967296*(b-a+1));};const mix=a=>{for(let i=a.length-1;i>0;i--){const j=rand(0,i);[a[i],a[j]]=[a[j],a[i]];}return a;};
 const n=byNode[node];if(!n)throw Error('Unknown discovery');const level=questionLevel(index),object=WORLD_OBJECTS[n.world][(index+(seed%3))%3],thing=OBJECTS[object].many;
 let a,b,c,answer,prompt,display='',hint,visual=null,choices,form=index%3===0?'story':index%3===1?'visual':'symbolic';
 const cap=[5,8,10][level-1];
 switch(node){
 case 'count5':case 'count20':a=rand(node==='count5'?1:6,node==='count5'?5:level===1?10:20);answer=a;prompt=`How many ${thing} can you count?`;visual={type:'count',a};hint=`Tap each ${OBJECTS[object].one} once. Count in order from 1${a>1?' to '+a:''}. Only the real objects count.`;if(form==='symbolic'){prompt='Which number comes next?';display=`${Math.max(0,a-2)}, ${a-1}, ?`;visual=null;hint=`The numbers go up by 1: ${Math.max(0,a-2)}, then ${a-1}. Add 1 to ${a-1}.`;}break;
 case 'compare':a=rand(1,level===1?10:20);b=a+rand(1,5);answer=b;prompt=`Which group has more ${thing}?`;display=`${a} or ${b}`;hint=`Compare ${a} and ${b}. Start at ${a}; ${b} is ${b-a} steps farther along the number line.`;if(form==='visual')visual={type:'compare',a,b};break;
 case 'add10':a=rand(1,cap-1);b=rand(1,Math.max(1,Math.min(10-a,cap)));answer=a+b;prompt=form==='story'?`Nova finds ${a} ${thing}, then ${b} more. How many altogether?`:'Bring the two groups together.';display=`${a} + ${b} = ?`;hint=`Start at ${a}. Count on ${b}: ${Array.from({length:b},(_,i)=>a+i+1).join(', ')}.`;if(form==='visual')visual={type:'add',a,b};break;
 case 'subtract10':a=rand(2,cap);b=rand(1,a);answer=a-b;prompt=form==='story'?`There are ${a} ${thing}. Move ${b} away. How many remain?`:'Find what stays behind.';display=`${a} − ${b} = ?`;hint=`Start with ${a}. Cross out ${b}, then count what remains.`;if(form==='visual')visual={type:'subtract',a,b};break;
 case 'shapes':a=['triangle','square','rectangle','pentagon'][rand(0,level===1?2:3)];answer=a==='triangle'?3:a==='pentagon'?5:4;prompt='How many sides does this shape have?';visual={type:'shape',shape:a};hint=`Trace the ${a}. Count its straight edges, not its corners twice. ${a==='rectangle'?'Two long edges and two short edges make its outline.':a==='triangle'?'Follow the bottom and its two sloping edges.':a==='square'?'Follow the top, right, bottom, and left edges.':'Follow the five straight edges around the outside.'}`;if(form==='symbolic'){prompt=`How many sides does a ${a} have?`;visual=null;}choices=[3,4,5,6];break;
 case 'tens':a=rand(1,level===1?4:9);b=rand(0,9);answer=a*10+b;prompt=form==='story'?`Pack ${a} bundles of 10 ${thing}, with ${b} left over. How many?`:'Build this number.';display=`${a} tens + ${b} ones`;hint=`${a} tens is ${a*10}. Add ${b} ones.`;if(form==='visual')visual={type:'place',a,b};break;
 case 'hundreds':a=rand(1,level===1?4:9);b=rand(0,9);c=rand(0,9);answer=a*100+b*10+c;prompt='Build a number from its parts.';display=`${a} hundreds + ${b} tens + ${c} ones`;hint=`Put ${a} in the hundreds place, ${b} in the tens place, and ${c} in the ones place.`;if(form==='visual')visual={type:'place-labels',a,b,c};break;
 case 'add100':a=rand(10,49);b=rand(10,49);answer=a+b;prompt=form==='story'?`There are ${a} ${thing} on one platform and ${b} on another. How many together?`:'Add the two numbers.';display=`${a} + ${b} = ?`;hint=`Add tens: ${Math.floor(a/10)*10} + ${Math.floor(b/10)*10}. Add ones: ${a%10} + ${b%10}. Combine both totals.`;if(form==='visual')visual={type:'decompose',a,b};break;
 case 'groups':case 'multiply':a=rand(2,node==='groups'?4:level*3+1);b=rand(2,node==='groups'?5:level*3+1);answer=a*b;prompt=form==='story'?`${a} baskets each hold ${b} ${thing}. How many altogether?`:'How many in these equal groups?';display=form==='symbolic'?`${a} × ${b} = ?`:`${a} groups of ${b}`;hint=`Add ${b}, ${a} times: ${Array(a).fill(b).join(' + ')}.`;if(form==='visual')visual={type:'groups',a,b};break;
 case 'area':a=rand(2,level*3+1);b=rand(2,level*2+1);answer=a*b;prompt='How many square units cover this rectangle?';display=`${a} units × ${b} units`;hint=`There are ${a} columns and ${b} rows. Multiply ${a} by ${b}.`;if(form!=='symbolic')visual={type:'area',a,b};break;
 case 'share':case 'divide':b=rand(2,node==='share'?4:level*3+1);answer=rand(1,node==='share'?5:level*3+1);a=b*answer;prompt=`Share ${a} ${thing} equally among ${b} baskets. How many per basket?`;display=`${a} ÷ ${b} = ?`;hint=`Ask: ${b} equal groups of what make ${a}? Try putting one in every basket at a time.`;if(form==='visual')visual={type:'share',a,b};break;
 case 'halves':case 'fractions':b=node==='halves'?[2,4][rand(0,1)]:[3,4,5,6,8][rand(0,level+1)];a=rand(1,b-1);answer=`${a}/${b}`;prompt=form==='symbolic'?`${a} of ${b} equal pieces are lit. What fraction is lit?`:'What fraction of the whole is lit?';hint=`The whole has ${b} equal pieces. ${a} are lit: ${a}/${b}.`;if(form!=='symbolic')visual={type:'fraction',a,b};choices=[answer,`${b}/${b}`,`${a}/${b+1}`,`${a-1}/${b}`];break;
 case 'equivalent':b=rand(2,level+3);a=rand(1,b-1);c=rand(2,level+2);answer=a*c;display=`${a}/${b} = ?/${b*c}`;prompt='Keep the same amount. Find the missing top number.';hint=`The bottom was multiplied by ${c}. Multiply the top ${a} by ${c} too.`;if(form==='visual')visual={type:'equivalent',a,b,c};break;
 case 'addFractions':b=[4,6,8,10][rand(0,level)];a=rand(1,b-2);c=rand(1,b-a);answer=`${a+c}/${b}`;display=`${a}/${b} + ${c}/${b} = ?`;prompt='Join pieces that have the same size.';hint=`Keep ${b} as the bottom number. Add ${a} and ${c} on top.`;if(form==='visual')visual={type:'fraction-add',a,b,c};choices=[answer,`${a+c}/${2*b}`,`${a+c-1}/${b}`,`${a+c+1}/${b}`];break;
 case 'length':a=rand(1,level*5);b=rand(1,level*5);answer=a+b;display=`${a} cm + ${b} cm = ? cm`;prompt='Join two paths. How long is the new path?';hint=`Add ${a} and ${b}. Both measurements use centimetres.`;if(form==='visual')visual={type:'ruler',a,b};break;
 case 'convert':a=rand(1,level*4);answer=a*100;display=`${a} m = ? cm`;prompt='Measure a bridge in centimetres.';hint=`1 metre is 100 centimetres. Multiply ${a} by 100.`;if(form==='visual')visual={type:'convert',a};break;
 case 'tenths':a=rand(1,9);answer=(a/10).toFixed(1);prompt='Write the lit part as a decimal.';display=form==='symbolic'?`${a}/10 = ?`:'';hint=`${a} tenths is written 0.${a}. The first place after the dot counts tenths.`;if(form!=='symbolic')visual={type:'fraction',a,b:10};choices=[answer,`${a}.0`,(Math.max(0,a-1)/10).toFixed(1),(Math.min(10,a+1)/10).toFixed(1)];break;
 case 'decimals':a=rand(1,9);b=rand(1,9);answer=(a+b/10).toFixed(1);display=`${a} ones + ${b} tenths = ?`;prompt='Build a decimal from its places.';hint=`Write ${a} before the dot and ${b} after it: ${a}.${b}.`;choices=[answer,(a+(b-1)/10).toFixed(1),(a+(b+1)/10).toFixed(1),(a+1+b/10).toFixed(1)];if(form==='visual')visual={type:'decimal-place',a,b};break;
 case 'decimalAdd':a=rand(1,level*15);b=rand(1,level*15);answer=((a+b)/10).toFixed(1);display=`${(a/10).toFixed(1)} + ${(b/10).toFixed(1)} = ?`;prompt='Join two lengths measured in tenths.';hint=`${a} tenths + ${b} tenths = ${a+b} tenths. Ten tenths make one whole.`;choices=[answer,((a+b+1)/10).toFixed(1),((a+b+10)/10).toFixed(1),((a+b-1)/10).toFixed(1)];if(form==='visual')visual={type:'decimal-split',a,b};break;
 case 'multiMultiply':a=rand(12,level*15+10);b=rand(2,level+4);answer=a*b;display=`${a} × ${b} = ?`;prompt=form==='story'?`${b} crates each hold ${a} ${thing}. How many altogether?`:'Multiply by splitting the larger number.';hint=`${Math.floor(a/10)*10} × ${b} = ${Math.floor(a/10)*10*b}; ${a%10} × ${b} = ${a%10*b}. Add both parts.`;if(form==='visual')visual={type:'multiply-split',a,b};break;
 }
 if(!choices){const set=new Set([answer]);let offset=1;while(set.size<4){set.add(answer+offset);if(answer-offset>=0&&set.size<4)set.add(answer-offset);offset++;}choices=[...set];}
 choices=mix([...new Set(choices)]);if(choices.length!==4)throw Error(`Choice collision in ${node}`);
 if(visual)visual.object=object;
 const steps={count5:visual?`Count: ${Array.from({length:a},(_,i)=>i+1).join(', ')}. There ${a===1?'is':'are'} ${a} ${a===1?OBJECTS[object].one:thing}.`:`${a-1} + 1 = ${a}. So the next number is ${a}.`,count20:visual?`Count in groups of five, then the leftovers. The total is ${a} ${thing}.`:`${a-1} + 1 = ${a}.`,compare:`${b} is greater than ${a} because it has ${b-a} more.`,add10:`${a} + ${b} = ${answer}. The two groups together have ${answer} ${thing}.`,subtract10:`${a} − ${b} = ${answer}. After moving ${b} away, ${answer} remain.`,shapes:`A ${a} has ${answer} straight sides.`,tens:`${a} × 10 + ${b} = ${answer}.`,hundreds:`${a*100} + ${b*10} + ${c} = ${answer}.`,add100:`${Math.floor(a/10)*10+Math.floor(b/10)*10} tens-value + ${a%10+b%10} ones = ${answer}.`,groups:`${a} groups of ${b} make ${answer}.`,multiply:`${a} × ${b} = ${answer}.`,area:`${a} columns × ${b} rows = ${answer} square units.`,share:`${b} baskets × ${answer} each = ${a} altogether.`,divide:`${a} ÷ ${b} = ${answer}, because ${b} × ${answer} = ${a}.`,halves:`${a} lit pieces out of ${b} equal pieces is ${answer}.`,fractions:`The top counts lit pieces (${a}); the bottom counts all pieces (${b}). That is ${answer}.`,equivalent:`${a} × ${c} = ${answer}; ${b} × ${c} = ${b*c}. Both parts grow by the same factor.`,addFractions:`${a} + ${c} = ${a+c}. The pieces stay the same size: ${answer}.`,length:`${a} + ${b} = ${answer} centimetres.`,convert:`${a} × 100 = ${answer} centimetres.`,tenths:`${a} ÷ 10 = ${answer}.`,decimals:`${a} whole ones plus ${b} tenths is ${answer}.`,decimalAdd:`${a} + ${b} = ${a+b} tenths, written ${answer}.`,multiMultiply:`${Math.floor(a/10)*10*b} + ${a%10*b} = ${answer}.`};
 return {id:n.skill,node,index,seed,level,form,answer,prompt,display,hint,worked:steps[node],visual,choices,object,timeLimit:questionSeconds(node)};
}
